/**
 * Generates placeholder content modules for every guide, use-case and
 * comparison page so route shells always resolve while the real articles are
 * written. Each stub declares the same exports as a finished module.
 */
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'

const root = process.cwd()

const PREAMBLE = `/**
 * Placeholder generated by scripts/gen-stubs.mjs.
 * Replace the body, sections, faqs and sources with the real article.
 * Contract: src/lib/content-types.ts (named export \`meta\`, default export component).
 */
`

const LEARN = [
  ['json', 'JSON: The Complete Specification Guide', 22],
  ['csv', 'CSV: The Complete Format Guide', 20],
  ['yaml', 'YAML: The Complete Guide', 24],
  ['xml', 'XML: The Complete Guide', 23],
  ['base64', 'Base64: The Complete Encoding Guide', 19],
]

const USE_CASES = [
  ['api-debugging', 'Tools for Debugging HTTP APIs', 12],
  ['data-migration', 'Tools for Migrating Data Between Systems', 13],
  ['config-conversion', 'Tools for Converting Configuration Files', 12],
  ['log-analysis', 'Tools for Reading Structured Logs', 12],
  ['test-data', 'Tools for Building Test Fixtures', 12],
  ['encoding', 'Encoding Tools with Security Consequences', 13],
]

const COMPARES = [
  ['json-vs-csv', 'JSON vs CSV', 11],
  ['yaml-vs-json', 'YAML vs JSON', 11],
  ['xml-vs-json', 'XML vs JSON', 11],
  ['csv-vs-tsv', 'CSV vs TSV', 10],
  ['yaml-vs-toml', 'YAML vs TOML', 10],
  ['csv-vs-excel', 'CSV vs Excel', 11],
  ['yaml-vs-xml', 'YAML vs XML', 10],
]

function stub(group, slug, h1, minutes) {
  return `${PREAMBLE}
import { P, Section } from '@/components/content'
import type { ArticleMeta } from '@/lib/content-types'

export const meta: ArticleMeta = {
  slug: '${slug}',
  path: '/${group}/${slug}/',
  title: '${h1} | ConvertTools',
  description: 'Placeholder description for /${group}/${slug}/ — replace with 150 to 160 characters of real copy.',
  h1: '${h1}',
  summary: 'Placeholder summary.',
  keywords: ['${slug}'],
  published: '2026-11-02',
  updated: '2026-11-02',
  readingMinutes: ${minutes},
  sections: [{ id: 'overview', label: 'Overview' }],
  faqs: [{ question: 'Is this page written yet?', answer: 'No — this is a build placeholder.' }],
  sources: [{ label: 'Example source', href: 'https://example.org', detail: 'Placeholder reference.', accessed: '2026-11-12' }],
  related: [{ path: '/json-tools/formatter/', name: 'JSON Formatter', blurb: 'Beautify and validate JSON in the browser.' }],
  words: 100,
}

export default function Article() {
  return (
    <Prose>
      <Section id="overview" title="Overview">
        <P>This article has not been written yet. The shell, schema, table of contents and navigation are already wired up.</P>
      </Section>
    </Prose>
  )
}
`
}

const jobs = [
  ...LEARN.map(([slug, h1, minutes]) => ['learn', slug, h1, minutes]),
  ...USE_CASES.map(([slug, h1, minutes]) => ['use-cases', slug, h1, minutes]),
  ...COMPARES.map(([slug, h1, minutes]) => ['compare', slug, h1, minutes]),
]

let created = 0
for (const [group, slug, h1, minutes] of jobs) {
  const file = join(root, 'src', 'content', group, `${slug}.tsx`)
  mkdirSync(dirname(file), { recursive: true })
  if (!existsSync(file)) {
    writeFileSync(file, stub(group, slug, h1, minutes), 'utf8')
    created++
  }
}

console.log(`generated ${created} stub module(s), skipped ${jobs.length - created} existing`)
